def interactive(i):
 if i==0:
  return '''<div class="evidence"><div class="evidence-head"><p class="eyebrow">ORIGINAL POWER BI REPORT</p><button class="text-link" data-lightbox>Open full dashboard ↗</button></div><button class="dashboard-open" data-lightbox aria-label="Enlarge original Power BI dashboard"><img src="../assets/customer-dashboard.webp" width="1272" height="691" alt="Original Customer Behavior Power BI dashboard" loading="lazy"></button><p class="caption">Original Power BI report. Enlarge the image to inspect the details.</p></div>'''
 if i==1:
  return aml_visual()+'''<div class="explorer" data-explorer="aml"><p class="eyebrow">THE EVALUATION QUESTION</p><h3>Which metric deserves attention?</h3><div class="view-buttons" role="group" aria-label="Explore model evaluation"><button class="active" aria-pressed="true" data-view="accuracy">Accuracy</button><button aria-pressed="false" data-view="precision">Precision</button><button aria-pressed="false" data-view="recall">Recall</button><button aria-pressed="false" data-view="prauc">PR-AUC</button></div><div class="explain-panel" aria-live="polite"><strong data-panel-title>The majority-class trap</strong><p data-panel-text>With a positive rate of 0.104%, an all-negative classifier would be about 99.896% accurate and detect zero positive cases. This is a class-distribution calculation, not a reported model result.</p></div><small>Conceptual evaluation guide. No model performance is simulated.</small></div>'''
 if i==2:
  return rag_visual()+'''<div class="explorer" data-explorer="rag"><p class="eyebrow">EXPLORE THE ARCHITECTURE</p><h3>How a question becomes a grounded answer.</h3><div class="view-buttons" role="group" aria-label="Explore RAG stages"><button class="active" aria-pressed="true" data-view="index">01 · Index</button><button aria-pressed="false" data-view="retrieve">02 · Retrieve</button><button aria-pressed="false" data-view="rerank">03 · Rerank</button><button aria-pressed="false" data-view="generate">04 · Generate</button></div><div class="explain-panel" aria-live="polite"><strong data-panel-title>Organize the knowledge</strong><p data-panel-text>Enterprise documents are prepared and indexed so their content can be retrieved. This is the foundation for connecting a user’s question to source material.</p></div><small>Architecture walkthrough, not a live AI chat. No documents or questions are uploaded.</small></div>'''
 if i==3:
  return nlp_visual()+'''<div class="explorer" data-explorer="nlp"><p class="eyebrow">COMPARE THE APPROACHES</p><h3>Same text. Different ways to learn.</h3><div class="view-buttons" role="group" aria-label="Explore sentiment methods"><button class="active" aria-pressed="true" data-view="vader">VADER</button><button aria-pressed="false" data-view="tfidf">TF-IDF + ML</button><button aria-pressed="false" data-view="lstm">LSTM</button></div><div class="explain-panel" aria-live="polite"><strong data-panel-title>Start with a sentiment lexicon</strong><p data-panel-text>VADER scores the written review directly using a sentiment lexicon and rules. Star ratings are a comparison signal, not the input to VADER.</p></div><small>Method comparison based on the academic notebook. No live classifier or invented scores.</small></div>'''
 return mesh_visual()+'''<div class="explorer" data-explorer="mesh"><p class="eyebrow">FOLLOW THE RESEARCH</p><h3>Preserve the meaning. Reduce the payload.</h3><div class="view-buttons" role="group" aria-label="Explore research evaluation"><button class="active" aria-pressed="true" data-view="images">Image evaluation</button><button aria-pressed="false" data-view="relay">Device relay</button><button aria-pressed="false" data-view="simulation">Mesh simulation</button></div><div class="explain-panel" aria-live="polite"><strong data-panel-title>236 disaster-related images</strong><p data-panel-text>Generative model combinations were evaluated for reconstruction quality, including semantic fidelity, structural similarity, and hallucination trade-offs.</p></div><small>Research walkthrough. The illustration is not a live network or experimental result plot.</small></div>'''

def cases():
 for i,p in enumerate(P):
  nextp=P[(i+1)%len(P)]
  steps=''.join(f'<div class="approach-step"><span>0{j+1}</span><div><h3>{h}</h3><p>{text}</p></div></div>' for j,(h,text) in enumerate(p['steps']))
  findings=''.join(f'<article><span>0{j+1}</span><h3>{h}</h3><p>{text}</p></article>' for j,(h,text) in enumerate(p['findings']))
  body=header('../')+f'''<main id="main"><section class="case-hero section"><div class="case-topbar"><a class="back-link" href="../index.html#work">← Selected work</a>{project_picker(p["id"])}</div><div class="section-top"><p class="eyebrow">{p['label']}</p><span class="index-note">CASE STUDY / 0{i+1}</span></div><h1>{p['name']}</h1><p class="case-intro">{p['intro']}</p><div class="case-actions">{ext(GITHUB+'/'+p['repo'],'Explore the repository','button dark')}{('<a class="quiet-link" href="../assets/customer-shopping-presentation.pdf" target="_blank" rel="noopener">View presentation ↗</a>' if i==0 else '')}</div>{metric_row(p['metrics'])}</section><section class="case-body section"><aside class="case-aside"><p class="eyebrow">IN THIS CASE STUDY</p><nav aria-label="Case study sections"><a href="#question">The question</a><a href="#evidence">Explore the work</a><a href="#approach">The approach</a><a href="#findings">What I learned</a><a href="#limitations">Scope & limitations</a></nav>{tags(p['tools'])}</aside><div class="case-content"><section id="question"><p class="eyebrow">01 / THE QUESTION</p><h2>The business context.</h2><p class="body-large">{p['problem']}</p></section><section id="evidence"><p class="eyebrow">02 / EXPLORE THE WORK</p>{interactive(i)}</section><section id="approach"><p class="eyebrow">03 / THE APPROACH</p><h2>From question to evidence.</h2><div class="approach-list">{steps}</div></section><section id="findings"><p class="eyebrow">04 / WHAT I LEARNED</p><h2>The useful part of the analysis.</h2><div class="findings">{findings}</div><blockquote>{p['takeaway']}</blockquote></section><section id="limitations" class="limitations"><p class="eyebrow">05 / SCOPE & LIMITATIONS</p><h3>What the evidence does—and doesn’t—say.</h3><p>{p['limit']}</p>{ext(GITHUB+'/'+p['repo'],'Inspect the source material','text-link')}</section></div></section><a class="next-project section" href="{nextp['id']}.html"><span class="eyebrow">NEXT CASE STUDY / 0{((i+1)%5)+1}</span><span>{nextp['title']}</span><b aria-hidden="true">↗</b></a>{contact('../')}</main>'''+(dialog('../') if i==0 else '')
  (OUT/'projects'/f"{p['id']}.html").write_text(shell(f"{p['title']} — Abanoub Benyamin",p['intro'],body,'../'))

